#include "bsp/native_renderer_record_array_cleanup.hpp"
#include "bsp/singleton_lifetime.hpp"
#include "native_renderer_member_reference.hpp"
#include <Windows.h>
#include <array>
#include <cstdio>
#include <cstring>
#include <stdexcept>

namespace {
void require(bool value,const char* message) { if(!value) throw std::runtime_error(message); }
using Operation=void (__fastcall*)(void*,std::uint32_t,std::int32_t);
using Destroy=void (__fastcall*)(void*);
struct Header { void* data; std::int32_t count,capacity; };
static_assert(sizeof(Header)==12);
struct Frame { std::uint32_t before=0x13579bdfu; Header header{}; std::uint32_t after=0x2468ace0u; };
void guards(const Frame& f) { require(f.before==0x13579bdfu&&f.after==0x2468ace0u,"header guards"); }
void* __cdecl allocate_original(std::uint32_t bytes) {
    return bsp::singleton_lifetime_allocate({bsp::SingletonAllocationKind::pointer_slots,bytes,bytes});
}
void __cdecl free_original(void* data) noexcept { bsp::singleton_lifetime_free(data); }
class Original {
    void* code_; std::size_t length_;
public:
    template<std::size_t N> explicit Original(const unsigned char (&bytes)[N]):
        code_(VirtualAlloc(nullptr,N,MEM_COMMIT|MEM_RESERVE,PAGE_READWRITE)),length_(N) {
        require(code_!=nullptr,"VirtualAlloc"); std::memcpy(code_,bytes,N);
    }
    ~Original() { VirtualFree(code_,0,MEM_RELEASE); }
    template<class F> void bind(std::size_t offset,F target) {
        auto* code=static_cast<unsigned char*>(code_);
        require(code[offset]==0xe8,"CALL relocation");
        const auto relative=static_cast<std::uint32_t>(reinterpret_cast<std::uintptr_t>(target)-reinterpret_cast<std::uintptr_t>(code+offset+5));
        std::memcpy(code+offset+1,&relative,4);
    }
    void finish() {
        DWORD previous;
        require(VirtualProtect(code_,length_,PAGE_EXECUTE_READ,&previous)!=0,"VirtualProtect");
        require(FlushInstructionCache(GetCurrentProcess(),code_,length_)!=0,"FlushInstructionCache");
    }
    Operation operation() const { return reinterpret_cast<Operation>(code_); }
    Destroy destroy() const { return reinterpret_cast<Destroy>(code_); }
};
using Outcome=std::array<std::uint32_t,7>;
void allocate(Frame& frame,std::uint32_t count) {
    frame.header.data=allocate_original(count*4u);
    frame.header.count=static_cast<std::int32_t>(count);
    frame.header.capacity=static_cast<std::int32_t>(count);
    auto* cells=static_cast<std::uint32_t*>(frame.header.data);
    for(std::uint32_t i=0;i<count;++i) cells[i]=0x12345678u+i;
}
Outcome run_resize(Operation operation,int scenario) {
    Frame f; std::uint32_t prefix[4]={0x11111111u,0x22222222u,0x33333333u,0x44444444u};
    if(scenario<2) allocate(f,scenario==0?1u:3u);
    else if(scenario==2) f.header={prefix+1,-1,2};
    else f.header={reinterpret_cast<void*>(4u),-1,0};
    void* const old=f.header.data;
    const std::int32_t request=scenario==0?3:(scenario==1?1:0);
    operation(&f.header,0,request); guards(f);
    require(f.header.count==request,"resize count");
    Outcome result{static_cast<std::uint32_t>(f.header.count),static_cast<std::uint32_t>(f.header.capacity),f.header.data==old,0,0,0,f.after};
    if(scenario<2) {
        auto* cells=static_cast<std::uint32_t*>(f.header.data);
        require(f.header.capacity==3,"resize capacity");
        require((f.header.data==old)==(scenario==1),"resize current allocation");
        require(cells[0]==0x12345678u,"resize first cell retained");
        require(cells[1]==(scenario==0?0u:0x12345679u)&&cells[2]==(scenario==0?0u:0x1234567au),"new cells zero, removed cells retained");
        result[3]=cells[0]; result[4]=cells[1]; result[5]=cells[2]; free_original(f.header.data);
    } else if(scenario==2) {
        require(prefix[0]==0&&prefix[1]==0x22222222u&&prefix[2]==0x33333333u&&prefix[3]==0x44444444u,"signed negative index initialization");
        result[3]=prefix[0]; result[4]=prefix[1]; result[5]=prefix[3];
    } else require(f.header.data==old&&f.header.capacity==0,"null destination skip postimage");
    return result;
}
Outcome run_destroy(Destroy destroy,int scenario) {
    Frame f;
    if(scenario!=2) allocate(f,scenario==0?2u:1u);
    if(scenario==1) f.header.capacity=-1;
    void* const old=f.header.data;
    destroy(&f.header); guards(f);
    require(f.header.count==0,"destroy final count");
    require(f.header.capacity==(scenario==0?2:(scenario==1?1:0)),"destroy retained capacity");
    require((f.header.data==old)==(scenario!=1),"destroy stale current data");
    return {0,static_cast<std::uint32_t>(f.header.capacity),f.header.data==old,f.header.data==nullptr,0,0,f.after};
}
void report_runtime_modules() {
    const wchar_t* names[]={L"ucrtbase.dll",L"vcruntime140.dll",L"msvcp140.dll",L"vcruntime140_1.dll"};
    for(const auto* name:names) {
        HMODULE module=GetModuleHandleW(name);
        if(module==nullptr) { std::printf("UNLOADED_RUNTIME|%ls\n",name); continue; }
        wchar_t reported[1024],canonical[1024];
        const auto length=GetModuleFileNameW(module,reported,1024);
        require(length!=0&&length<1024,"loaded module path");
        HANDLE file=CreateFileW(reported,GENERIC_READ,FILE_SHARE_READ|FILE_SHARE_WRITE|FILE_SHARE_DELETE,nullptr,OPEN_EXISTING,FILE_ATTRIBUTE_NORMAL,nullptr);
        require(file!=INVALID_HANDLE_VALUE,"loaded module file");
        const auto final_length=GetFinalPathNameByHandleW(file,canonical,1024,FILE_NAME_NORMALIZED);
        CloseHandle(file); require(final_length!=0&&final_length<1024,"canonical module file");
        const auto* base=reinterpret_cast<const unsigned char*>(module);
        const auto* dos=reinterpret_cast<const IMAGE_DOS_HEADER*>(base);
        const auto* nt=reinterpret_cast<const IMAGE_NT_HEADERS32*>(base+dos->e_lfanew);
        require(nt->FileHeader.Machine==IMAGE_FILE_MACHINE_I386,"loaded runtime machine");
        std::printf("LOADED_RUNTIME|%ls|%ls|%ls|%04x\n",name,reported,canonical,static_cast<unsigned>(nt->FileHeader.Machine));
    }
}
}
int main() {
    try {
        Original vertex_reserve(original_00b22dd0),pixel_reserve(original_00b22e30),third_reserve(original_00b22650);
        for(auto* body:{&vertex_reserve,&pixel_reserve,&third_reserve}) {
            body->bind(0x20,&allocate_original); body->bind(0x4c,&free_original); body->finish();
        }
        Original vertex_resize(original_00b25cf0),pixel_resize(original_00b25d40),third_resize(original_00b22e90);
        vertex_resize.bind(0xe,vertex_reserve.operation()); pixel_resize.bind(0xe,pixel_reserve.operation()); third_resize.bind(0xe,third_reserve.operation());
        vertex_resize.finish(); pixel_resize.finish(); third_resize.finish();
        Original vertex_destroy(original_00b29b60),pixel_destroy(original_00b29b80),third_destroy(original_00b28090);
        vertex_destroy.bind(5,vertex_resize.operation()); pixel_destroy.bind(5,pixel_resize.operation()); third_destroy.bind(5,third_resize.operation());
        for(auto* body:{&vertex_destroy,&pixel_destroy,&third_destroy}) { body->bind(13,&free_original); body->finish(); }
        const Operation originals[]={vertex_resize.operation(),pixel_resize.operation(),third_resize.operation()};
        const Operation sources[]={&bsp::resize_native_renderer_vertex_shader_registry_00b25cf0,&bsp::resize_native_renderer_pixel_shader_registry_00b25d40,&bsp::resize_native_renderer_third_state_cache_00b22e90};
        const Destroy old_destroy[]={vertex_destroy.destroy(),pixel_destroy.destroy(),third_destroy.destroy()};
        const Destroy new_destroy[]={&bsp::destroy_native_renderer_vertex_shader_registry_00b29b60,&bsp::destroy_native_renderer_pixel_shader_registry_00b29b80,&bsp::destroy_native_renderer_third_state_cache_00b28090};
        for(int kind=0;kind<3;++kind) {
            for(int scenario=0;scenario<4;++scenario) require(run_resize(originals[kind],scenario)==run_resize(sources[kind],scenario),"original/source resize");
            for(int scenario=0;scenario<3;++scenario) require(run_destroy(old_destroy[kind],scenario)==run_destroy(new_destroy[kind],scenario),"original/source destroy");
        }
        report_runtime_modules();
        std::puts("PASS: three complete original member cleanup chains versus shared source; 21 comparisons");
        return 0;
    } catch(const std::exception& error) { std::fprintf(stderr,"FAIL: %s\n",error.what()); return 1; }
}

